+package org.logstash.plugins.pipeline;
+
+import com.google.common.annotations.VisibleForTesting;
+import org.apache.logging.log4j.LogManager;
+import org.apache.logging.log4j.Logger;
+import org.logstash.ext.JrubyEventExtLibrary;
+
+import java.util.*;
+import java.util.concurrent.ConcurrentHashMap;
+import java.util.function.Consumer;
+import java.util.stream.Collectors;
+import java.util.stream.StreamSupport;
+
+class PipelineEventBusV2 extends AbstractPipelineBus implements PipelineBus {
+
+    // The canonical source of truth for mapping addresses to their AddressStates
+    protected final AddressStateMap addressStates = new AddressStateMap();
+
+    // A cached mapping from any given registered sender (PipelineOutput) to a query-only view of
+    // the AddressState-s to which it is registered.
+    protected final Map<PipelineOutput, Set<AddressState.ReadOnly>> addressStatesBySender = new ConcurrentHashMap<>();
+
+    // effectively a set-on-shutdown flag
+    protected volatile boolean blockOnUnlisten = false;
+
+    private static final Logger PIPELINE_LOG = LogManager.getLogger(PipelineEventBusV2.class);
+
+    @Override
+    public void sendEvents(final PipelineOutput outputEndpoint,
+                           final Collection<JrubyEventExtLibrary.RubyEvent> rubyEventCollection,
+                           final boolean guaranteeDelivery) {
+        if (rubyEventCollection.isEmpty()) return;
+
+        final Set<AddressState.ReadOnly> addressStateSet = addressStatesBySender.get(outputEndpoint);
+        if (addressStateSet == null) {
+            throw new IllegalStateException("cannot send events from unregistered sender");
+        }
+
+        // In case of retry on the same set events, a stable order is needed, else
+        // the risk is to reprocess twice some events. Collection can't guarantee order stability.
+        JrubyEventExtLibrary.RubyEvent[] orderedRubyEvents = rubyEventCollection.toArray(new JrubyEventExtLibrary.RubyEvent[0]);
+
+        addressStateSet.forEach(addrSnapshot -> doSendEvents(orderedRubyEvents, addrSnapshot, guaranteeDelivery));
+    }
+
+    @Override
+    public void registerSender(final PipelineOutput outputEndpoint,
+                               final Iterable<String> addressIterable) {
+        Objects.requireNonNull(outputEndpoint, "sender must not be null");
+        Objects.requireNonNull(addressIterable, "addresses must not be null");
+        addressStatesBySender.compute(outputEndpoint, (pipelineOutputInstance, existingSet) -> {
+            return StreamSupport.stream(addressIterable.spliterator(), false)
+                                .map((addressKey) -> addressStates.modify(addressKey, (addrStateRef) -> addrStateRef.addOutput(pipelineOutputInstance)))
+                                .collect(Collectors.toUnmodifiableSet());
+        });
+    }
+
+    @Override
+    public void unregisterSender(final PipelineOutput outputEndpoint,
+                                 final Iterable<String> addressIterable) {
+        Objects.requireNonNull(outputEndpoint, "sender must not be null");
+        Objects.requireNonNull(addressIterable, "addresses must not be null");
+        addressStatesBySender.compute(outputEndpoint, (pipelineOutputInstance, existingSet) -> {
+            addressIterable.forEach((addressKey) -> addressStates.modify(addressKey, (addrStateRef) -> addrStateRef.removeOutput(pipelineOutputInstance)));
+            return null;
+        });
+    }
+
+    @Override
+    public boolean listen(final PipelineInput inputListener,
+                          final String addressKey) {
+        Objects.requireNonNull(inputListener, "listener must not be null");
+        Objects.requireNonNull(addressKey, "address must not be null");
+        final AddressState.ReadOnly readOnlyResult = addressStates.modify(addressKey, (addrSnapshot) -> {
+            addrSnapshot.assignInputIfMissing(inputListener);
+        });
+        return (readOnlyResult != null && readOnlyResult.getInput() == inputListener);
+    }
+
+    @Override
+    public void unlisten(final PipelineInput inputListener,
+                         final String addressKey) throws InterruptedException {
+        Objects.requireNonNull(inputListener, "listener must not be null");
+        Objects.requireNonNull(addressKey, "address must not be null");
+        if (this.blockOnUnlisten) {
+            awaitUnlisten(inputListener, addressKey);
+        } else {
+            unassignInputNonblock(inputListener, addressKey);
+        }
+    }
+
+    private void unassignInputNonblock(final PipelineInput inputListener,
+                                       final String addressKey) {
+        addressStates.modify(addressKey, (addrSnapshot) -> addrSnapshot.unassignInput(inputListener));
+    }
+
+    private void awaitUnlisten(final PipelineInput inputListener,
+                               final String addressKey) throws InterruptedException {
+        synchronized (Objects.requireNonNull(inputListener, "listener must not be null")) {
+            while(!tryUnlistenIfOrphan(inputListener, addressKey)) {
+                inputListener.wait(10000);
+            }
+        }
+    }
+
+    /**
+     * Makes a singular attempt to unlisten to the address that succeeds if and only if
+     * there are no senders registered to the address
+     * @param inputListener the {@link PipelineInput} that to unlisten
+     * @param addressKey the address from which to unlisten
+     * @return true iff this listener is not listening after the attempt
+     */
+    private boolean tryUnlistenIfOrphan(final PipelineInput inputListener,
+                                        final String addressKey) {
+        final AddressState.ReadOnly readOnlyResult = addressStates.modify(addressKey, (addrSnapshot) -> {
+            final Set<PipelineOutput> outputSet = addrSnapshot.getOutputs();
+            if (outputSet.isEmpty()) {
+                addrSnapshot.unassignInput(inputListener);
+            } else {
+                PIPELINE_LOG.trace(() -> String.format("input `%s` is not ready to unlisten from `%s` because the address still has attached senders (%s)", inputListener.getId(), addressKey, outputSet.stream().map(PipelineOutput::getId).collect(Collectors.toSet())));
+            }
+        });
+        return readOnlyResult == null || readOnlyResult.getInput() != inputListener;
+    }
+
+    @Override
+    public void setBlockOnUnlisten(final boolean waitOnUnlisten) {
+        this.blockOnUnlisten = waitOnUnlisten;
+    }
+
+    protected static class AddressStateMap {
+
+        private final Map<String, AddressState> addressStateMap = new ConcurrentHashMap<>();
+
+        public AddressState.ReadOnly modify(final String addressKey,
+                                            final Consumer<AddressState> addressStateConsumer) {
+            final AddressState readOnlyResult = addressStateMap.compute(addressKey, (addrKey, addrSnapshot) -> {
+                if (addrSnapshot == null) {
+                    addrSnapshot = new AddressState(addressKey);
+                }
+
+                addressStateConsumer.accept(addrSnapshot);
+
+                // If this addressState has a listener, ensure that any waiting
+                // threads get notified so that they can resume immediately
+                final PipelineInput activeInput = addrSnapshot.getInput();
+                if (activeInput != null) {
+                    synchronized (activeInput) { activeInput.notifyAll(); }
+                }
+
+                return addrSnapshot.isEmpty() ? null : addrSnapshot;
+            });
+            return readOnlyResult == null ? null : readOnlyResult.getReadOnlyView();
+        }
+
+        private AddressState.ReadOnly get(final String addressKey) {
+            final AddressState readOnlyResult = addressStateMap.get(addressKey);
+            return readOnlyResult == null ? null : readOnlyResult.getReadOnlyView();
+        }
+    }
+
+    @VisibleForTesting
+    static class TestableAddressStateManager extends PipelineEventBusV2 implements PipelineBus.Testable {
+
+        @Override
+        @VisibleForTesting
+        public boolean isBlockOnUnlisten() {
+            return this.blockOnUnlisten;
+        }
+
+        @Override
+        @VisibleForTesting
+        public Optional<AddressState.ReadOnly> getAddressState(final String addressKey) {
+            return Optional.ofNullable(addressStates.get(addressKey));
+        }
+
+        @Override
+        @VisibleForTesting
+        public Optional<Set<AddressState.ReadOnly>> getAddressStates(final PipelineOutput outputEndpoint) {
+            return Optional.ofNullable(addressStatesBySender.get(outputEndpoint));
+        }
+
+    }
+}
