+package org.logstash.common.io;
+
+import java.io.Closeable;
+import java.io.IOException;
+import java.nio.channels.FileLock;
+import java.nio.file.Files;
+import java.nio.file.NoSuchFileException;
+import java.nio.file.Path;
+import java.nio.file.StandardCopyOption;
+import java.time.Clock;
+import java.time.Duration;
+import java.time.Instant;
+import java.time.temporal.TemporalAmount;
+import java.util.Comparator;
+import java.util.Locale;
+import java.util.Optional;
+import java.util.concurrent.Executors;
+import java.util.concurrent.ScheduledExecutorService;
+import java.util.concurrent.TimeUnit;
+import java.util.concurrent.atomic.AtomicBoolean;
+import java.util.concurrent.atomic.AtomicLong;
+import java.util.concurrent.atomic.LongAdder;
+import java.util.concurrent.locks.ReentrantLock;
+
+import com.google.common.annotations.VisibleForTesting;
+import org.apache.logging.log4j.LogManager;
+import org.apache.logging.log4j.Logger;
+import org.logstash.DLQEntry;
+import org.logstash.Event;
+import org.logstash.FieldReference;
+import org.logstash.FileLockFactory;
+import org.logstash.Timestamp;
+
+import static org.logstash.common.io.DeadLetterQueueUtils.listFiles;
+import static org.logstash.common.io.DeadLetterQueueUtils.listSegmentPaths;
+import static org.logstash.common.io.RecordIOReader.SegmentStatus;
+import static org.logstash.common.io.RecordIOWriter.BLOCK_SIZE;
+import static org.logstash.common.io.RecordIOWriter.RECORD_HEADER_SIZE;
+import static org.logstash.common.io.RecordIOWriter.VERSION_SIZE;
+
+public final class DeadLetterQueueFileWriter implements Closeable {
+
+    @VisibleForTesting
+    static final String SEGMENT_FILENAME_TEMPLATE = "%d.log";
+    private static final Logger LOG = LogManager.getLogger(DeadLetterQueueFileWriter.class);
+    private enum FinalizationTiming {ALWAYS, ONLY_IF_STALE};
+    private static final String TEMP_FILENAME_TEMPLATE = "%d.log.tmp";
+    private static final String LOCKFILE_PATH = ".lock";
+    private final ReentrantLock writeLock = new ReentrantLock();
+    private static final FieldReference DLQ_METADATA_KEY =
+        FieldReference.from(String.format("%s[dead_letter_queue]", Event.METADATA_BRACKETS));
+    private final long segmentSizeLimit;
+    private final long queueSizeLimit;
+    private final QueueStorageType storageMode;
+    private AtomicLong queueItemCount;
+    private final Path pathToQueue;
+    private final FileLock exclusiveFileLock;
+    private volatile RecordIOWriter activeWriter;
+    private int activeSegmentIndex;
+    private Timestamp previousEntryTimestamp;
+    private Duration flushPeriod;
+    private Instant lastWriteTime;
+    private final AtomicBoolean isInitialized = new AtomicBoolean(true);
+    private ScheduledExecutorService flushExecutor;
+    private final LongAdder droppedCount = new LongAdder();
+    private final LongAdder expiredCount = new LongAdder();
+    private String lastErrorMessage = "no errors";
+    private final Clock timeSource;
+    private Optional<Timestamp> oldestSegmentTime;
+    private Optional<Path> oldestSegmentLocation;
+    private final TemporalAmount retentionPeriod;
+
+    public static final class QueueBuilder {
+
+        private final Path pathToQueue;
+        private final long segmentSizeLimit;
+        private final long queueSizeLimit;
+        private final Duration flushPeriod;
+        private boolean enableScheduledFlush;
+        private QueueStorageType storageMode = QueueStorageType.DROP_NEWER;
+        private Duration retentionPeriod = null;
+        private Clock timeSource = Clock.systemDefaultZone();
+
+        private QueueBuilder(Path pathToQueue, long segmentSizeLimit, long queueSizeLimit, Duration flushPeriod) {
+            this(pathToQueue, segmentSizeLimit, queueSizeLimit, flushPeriod, true);
+        }
+
+        private QueueBuilder(Path pathToQueue, long segmentSizeLimit, long queueSizeLimit, Duration flushPeriod, boolean enableScheduledFlush) {
+            this.pathToQueue = pathToQueue;
+            this.segmentSizeLimit = segmentSizeLimit;
+            this.queueSizeLimit = queueSizeLimit;
+            this.flushPeriod = flushPeriod;
+            this.enableScheduledFlush = enableScheduledFlush;
+        }
+
+        public QueueBuilder withStorageType(QueueStorageType storageMode) {
+            this.storageMode = storageMode;
+            return this;
+        }
+
+        public QueueBuilder setRetentionTime(Duration retentionPeriod) {
+            this.retentionPeriod = retentionPeriod;
+            return this;
+        }
+
+        @VisibleForTesting
+        QueueBuilder setClock(Clock timeSource) {
+            this.timeSource = timeSource;
+            return this;
+        }
+
+        public DeadLetterQueueFileWriter buildWriter() throws IOException {
+            return new DeadLetterQueueFileWriter(pathToQueue, segmentSizeLimit, queueSizeLimit, flushPeriod, storageMode, retentionPeriod, timeSource, enableScheduledFlush);
+        }
+    }
+
+    public static QueueBuilder newQueueBuilder(final Path pathToQueue, final long segmentSizeLimit, final long queueSizeLimit,
+                                               final Duration flushPeriod) {
+        return new QueueBuilder(pathToQueue, segmentSizeLimit, queueSizeLimit, flushPeriod);
+    }
+
+    @VisibleForTesting
+    static QueueBuilder newQueueBuilderWithoutFlusher(final Path pathToQueue, final long segmentSizeLimit, final long queueSizeLimit) {
+        return new QueueBuilder(pathToQueue, segmentSizeLimit, queueSizeLimit, Duration.ZERO, false);
+    }
+
+    private DeadLetterQueueFileWriter(final Path pathToQueue, final long segmentSizeLimit, final long queueSizeLimit,
+                                      final Duration flushPeriod, final QueueStorageType storageMode, final Duration retentionPeriod,
+                                      final Clock timeSource, boolean enableScheduledFlush) throws IOException {
+        this.timeSource = timeSource;
+
+        this.exclusiveFileLock = FileLockFactory.obtainLock(pathToQueue, LOCKFILE_PATH);
+        this.pathToQueue = pathToQueue;
+        this.segmentSizeLimit = segmentSizeLimit;
+        this.queueSizeLimit = queueSizeLimit;
+        this.storageMode = storageMode;
+        this.flushPeriod = flushPeriod;
+        this.queueItemCount = new AtomicLong(calculateQueueSize());
+        this.retentionPeriod = retentionPeriod;
+
+        cleanupTempLogFiles();
+        refreshOldestSegmentReference();
+        activeSegmentIndex = listSegmentPaths(pathToQueue)
+                .map(sourcePath -> sourcePath.getFileName().toString().split("\\.")[0])
+                .mapToInt(Integer::parseInt)
+                .max().orElse(0);
+        openNextWriter();
+        this.previousEntryTimestamp = Timestamp.now();
+        if (enableScheduledFlush) {
+            initializeFlushScheduler();
+        }
+    }
+
+    public boolean isOpen() {
+        return isInitialized.get();
+    }
+
+    public Path getPath() {
+        return pathToQueue;
+    }
+
+    public long getCurrentQueueSize() {
+        return queueItemCount.longValue();
+    }
+
+    public String getStoragePolicy() {
+        return storageMode.name().toLowerCase(Locale.ROOT);
+    }
+
+    public long getDroppedEvents() {
+        return droppedCount.longValue();
+    }
+
+    public long getExpiredEvents() {
+        return expiredCount.longValue();
+    }
+
+    public String getLastError() {
+        return lastErrorMessage;
+    }
+
+    public void writeDeadLetterEntry(Event incomingEvent, String integrationName, String integrationId, String failureReason) throws IOException {
+        writeDeadLetterEntry(new DLQEntry(incomingEvent, integrationName, integrationId, failureReason));
+    }
+
+    @Override
+    public void close() {
+        if (isInitialized.compareAndSet(true, false)) {
+            try {
+                finalizeCurrentSegment(FinalizationTiming.ALWAYS);
+            } catch (Exception exception) {
+                LOG.warn("Unable to close dlq writer, ignoring", exception);
+            }
+            try {
+                releaseLock();
+            } catch (Exception exception) {
+                LOG.warn("Unable to release fileLock, ignoring", exception);
+            }
+
+            try {
+                flushExecutor.shutdown();
+            } catch (Exception exception) {
+                LOG.warn("Unable shutdown flush scheduler, ignoring", exception);
+            }
+        }
+    }
+
+    @VisibleForTesting
+    void writeDeadLetterEntry(DLQEntry dlqEntry) throws IOException {
+        writeLock.lock();
+        try {
+            Timestamp entryTime = Timestamp.now();
+            if (entryTime.compareTo(previousEntryTimestamp) < 0) {
+                entryTime = previousEntryTimestamp;
+            }
+            writeEntryInternal(dlqEntry);
+            previousEntryTimestamp = entryTime;
+        } finally {
+            writeLock.unlock();
+        }
+    }
+
+    private void writeEntryInternal(DLQEntry dlqEntry) throws IOException {
+        Event incomingEvent = dlqEntry.getEvent();
+
+        if (isAlreadyProcessed(incomingEvent)) {
+            LOG.warn("Event previously submitted to dead letter queue. Skipping...");
+            return;
+        }
+        byte[] serializedRecord = dlqEntry.serialize();
+        int payloadSize = RECORD_HEADER_SIZE + serializedRecord.length;
+        runAgeRetentionPolicy();
+        boolean shouldSkipWrite = enforceStoragePolicy(payloadSize);
+        if (shouldSkipWrite) {
+            return;
+        }
+
+        if (wouldExceedSegmentSize(payloadSize)) {
+            finalizeCurrentSegment(FinalizationTiming.ALWAYS);
+        }
+        long bytesWritten = activeWriter.writeEvent(serializedRecord);
+        queueItemCount.getAndAdd(bytesWritten);
+        lastWriteTime = Instant.now();
+    }
+
+    private boolean wouldExceedSegmentSize(int payloadSize) throws IOException {
+        return activeWriter.getPosition() + payloadSize > segmentSizeLimit;
+    }
+
+    private void runAgeRetentionPolicy() {
+        if (isOldestSegmentExpired()) {
+            try {
+                removeExpiredSegments();
+            } catch (IOException ioException) {
+                LOG.error("Can't remove some DLQ files while cleaning expired segments", ioException);
+            }
+        }
+    }
+
+    /**
+     * @param payloadSize payload size in bytes.
+     * @return boolean true if event write has to be skipped.
+     * */
+    private boolean enforceStoragePolicy(int payloadSize) {
+        if (!wouldExceedMaxQueueSize(payloadSize)) {
+            return false;
+        }
+
+        // load currentQueueSize from filesystem because there could be a consumer
+        // that's already cleaning
+        try {
+            this.queueItemCount.set(calculateQueueSize());
+        } catch (IOException ioException) {
+            LOG.warn("Unable to determine DLQ size, skipping storage policy check", ioException);
+            return false;
+        }
+
+        // after reload verify the condition is still valid
+        if (!wouldExceedMaxQueueSize(payloadSize)) {
+            return false;
+        }
+
+        if (storageMode == QueueStorageType.DROP_NEWER) {
+            lastErrorMessage = String.format("Cannot write event to DLQ(path: %s): reached maxQueueSize of %d", pathToQueue, queueSizeLimit);
+            LOG.error(lastErrorMessage);
+            droppedCount.add(1L);
+            return true;
+        } else {
+            try {
+                do {
+                    removeOldestSegment();
+                } while (wouldExceedMaxQueueSize(payloadSize));
+            } catch (IOException ioException) {
+                LOG.error("Can't remove some DLQ files while removing older segments", ioException);
+            }
+            return false;
+        }
+    }
+
+    private boolean wouldExceedMaxQueueSize(int payloadSize) {
+        return queueItemCount.longValue() + payloadSize > queueSizeLimit;
+    }
+
+    private boolean isOldestSegmentExpired() {
+        if (retentionPeriod == null) {
+            return false;
+        }
+        final Instant currentInstant = timeSource.instant();
+        return oldestSegmentTime
+                .map(timestamp -> timestamp.toInstant().isBefore(currentInstant.minus(retentionPeriod)))
+                .orElse(false);
+    }
+
+    private void removeExpiredSegments() throws IOException {
+        // remove all the old segments that verifies the age retention condition
+        boolean shouldCleanNextSegment;
+        do {
+            if (oldestSegmentLocation.isPresent()) {
+                Path removedSegment = oldestSegmentLocation.get();
+                expiredCount.add(deleteLastSegment(removedSegment, "age retention policy"));
+            }
+            refreshOldestSegmentReference();
+            shouldCleanNextSegment = isOldestSegmentExpired();
+        } while (shouldCleanNextSegment);
+
+        this.queueItemCount.set(calculateQueueSize());
+    }
+
+    /**
+     * Deletes the segment path, if present. Also return the number of events it contains.
+     *
+     * @param segmentPath
+     *      The segment file to delete.
+     * @param reason
+     *      Description of delete motivation.
+     * @return the number of events contained in the segment or 0 if the segment was already removed.
+     * @throws IOException if any other IO related error happens during deletion of the segment.
+     * */
+    private long deleteLastSegment(Path segmentPath, String reason) throws IOException {
+        try {
+            long segmentEventCount = DeadLetterQueueUtils.countEventsInSegment(segmentPath);
+            Files.delete(segmentPath);
+            LOG.debug("Removed segment file {} due to {}", reason, segmentPath);
+            return segmentEventCount;
+        } catch (NoSuchFileException noSuchFileException) {
+            // the last segment was deleted by another process, maybe the reader that's cleaning consumed segments
+            LOG.debug("File not found {}, maybe removed by the reader pipeline", segmentPath);
+            return 0;
+        }
+    }
+
+    private void refreshOldestSegmentReference() throws IOException {
+        oldestSegmentLocation = listSegmentPaths(this.pathToQueue).sorted().findFirst();
+        if (!oldestSegmentLocation.isPresent()) {
+            oldestSegmentTime = Optional.empty();
+            return;
+        }
+        // extract the newest timestamp from the oldest segment
+        Optional<Timestamp> discoveredTimestamp = readLastEventTimestampFromSegment(oldestSegmentLocation.get());
+        if (!discoveredTimestamp.isPresent()) {
+            // clean also the last segment, because doesn't contain a timestamp (corrupted maybe)
+            // or is not present anymore
+            oldestSegmentLocation = Optional.empty();
+        }
+        oldestSegmentTime = discoveredTimestamp;
+    }
+
+    /**
+     * Extract the timestamp from the last DLQEntry it finds in the given segment.
+     * Start from the end of the latest block, and going backward try to read the next event from its start.
+     * */
+    private static Optional<Timestamp> readLastEventTimestampFromSegment(Path pathToSegment) throws IOException {
+        final int finalBlockId = (int) Math.ceil(((Files.size(pathToSegment) - VERSION_SIZE) / (double) BLOCK_SIZE)) - 1;
+        byte[] eventDataBytes;
+        try (RecordIOReader reader = new RecordIOReader(pathToSegment)) {
+            int currentBlockId = finalBlockId;
+            do {
+                reader.seekToBlock(currentBlockId);
+                eventDataBytes = reader.readEvent();
+                currentBlockId--;
+            } while (eventDataBytes == null && currentBlockId >= 0); // no event present in last block, try with the one before
+        } catch (NoSuchFileException noSuchFileException) {
+            // the segment file may have been removed by the clean consumed feature on the reader side
+            return Optional.empty();
+        }
+        if (eventDataBytes == null) {
+            LOG.warn("Cannot find a complete event into the segment file [{}], this is a DLQ segment corruption", pathToSegment);
+            return Optional.empty();
+        }
+        return Optional.of(DLQEntry.deserialize(eventDataBytes).getEntryTime());
+    }
+
+    // package-private for testing
+    void removeOldestSegment() throws IOException {
+        // remove oldest segment
+        final Optional<Path> earliestSegment = listSegmentPaths(pathToQueue)
+                .min(Comparator.comparingInt(DeadLetterQueueUtils::extractSegmentId));
+        if (earliestSegment.isPresent()) {
+            final Path removedSegment = earliestSegment.get();
+            deleteLastSegment(removedSegment, "dead letter queue size exceeded dead_letter_queue.max_bytes size(" + queueSizeLimit + ")");
+        } else {
+            LOG.info("Queue size {} exceeded, but no complete DLQ segments found", queueSizeLimit);
