+public final class DeadLetterQueueSegmentWriter implements Closeable {
+
+    @VisibleForTesting
+    static final String SEGMENT_FILENAME_PATTERN = "%d.log";
+    private static final Logger DLQ_LOG = LogManager.getLogger(DeadLetterQueueSegmentWriter.class);
+    private enum FinalizationPolicy {ALWAYS, ONLY_IF_STALE};
+    private static final String TEMP_FILENAME_PATTERN = "%d.log.tmp";
+    private static final String SEGMENT_LOCK_PATH = ".lock";
+    private final ReentrantLock guard = new ReentrantLock();
+    private static final FieldReference DLQ_METADATA_KEY =
