+    private final long segmentSizeLimit;
+    private final long queueSizeLimit;
+    private final QueueStorageType queueStorageBackend;
+    private AtomicLong queueSizeCounter;
+    private final Path pathToQueue;
+    private final FileLock lockHandle;
+    private volatile RecordIOWriter activeWriter;
+    private int segmentIndex;
+    private Timestamp lastEventTimestamp;
+    private Duration flushPeriod;
+    private Instant lastWriteTime;
+    private final AtomicBoolean isOpen = new AtomicBoolean(true);
+    private ScheduledExecutorService flushExecutor;
+    private final LongAdder droppedCount = new LongAdder();
+    private final LongAdder expiredCount = new LongAdder();
+    private String lastErrorMessage = "no errors";
+    private final Clock timeSource;
+    private Optional<Timestamp> oldestSegmentTime;
+    private Optional<Path> oldestSegmentLocation;
+    private final TemporalAmount retentionDuration;
+
+    public static final class QueueConfigBuilder {
+
+        private final Path pathToQueue;
+        private final long segmentSizeLimit;
+        private final long queueSizeLimit;
+        private final Duration flushPeriod;
+        private boolean enableScheduledFlusher;
+        private QueueStorageType queueStorageBackend = QueueStorageType.DROP_NEWER;
+        private Duration retentionDuration = null;
+        private Clock timeSource = Clock.systemDefaultZone();
+
+        private QueueConfigBuilder(Path pathToQueue, long segmentSizeLimit, long queueSizeLimit, Duration flushPeriod) {
+            this(pathToQueue, segmentSizeLimit, queueSizeLimit, flushPeriod, true);
+        }
+
+        private QueueConfigBuilder(Path pathToQueue, long segmentSizeLimit, long queueSizeLimit, Duration flushPeriod, boolean enableScheduledFlusher) {
+            this.pathToQueue = pathToQueue;
+            this.segmentSizeLimit = segmentSizeLimit;
+            this.queueSizeLimit = queueSizeLimit;
+            this.flushPeriod = flushPeriod;
+            this.enableScheduledFlusher = enableScheduledFlusher;
+        }
+
+        public QueueConfigBuilder setStorageType(QueueStorageType queueStorageBackend) {
+            this.queueStorageBackend = queueStorageBackend;
+            return this;
+        }
+
+        public QueueConfigBuilder withRetentionTime(Duration retentionDuration) {
+            this.retentionDuration = retentionDuration;
+            return this;
+        }
+
+        @VisibleForTesting
+        QueueConfigBuilder setClock(Clock timeSource) {
+            this.timeSource = timeSource;
+            return this;
+        }
+
+        public DeadLetterQueueSegmentWriter buildWriter() throws IOException {
+            return new DeadLetterQueueSegmentWriter(pathToQueue, segmentSizeLimit, queueSizeLimit, flushPeriod, queueStorageBackend, retentionDuration, timeSource, enableScheduledFlusher);
+        }
+    }
+
+    public static QueueConfigBuilder newQueueConfigBuilder(final Path pathToQueue, final long segmentSizeLimit, final long queueSizeLimit,
+                                                           final Duration flushPeriod) {
+        return new QueueConfigBuilder(pathToQueue, segmentSizeLimit, queueSizeLimit, flushPeriod);
+    }
+
+    @VisibleForTesting
+    static QueueConfigBuilder newQueueConfigBuilderWithoutFlusher(final Path pathToQueue, final long segmentSizeLimit, final long queueSizeLimit) {
+        return new QueueConfigBuilder(pathToQueue, segmentSizeLimit, queueSizeLimit, Duration.ZERO, false);
+    }
+
+    private DeadLetterQueueSegmentWriter(final Path pathToQueue, final long segmentSizeLimit, final long queueSizeLimit,
+                                         final Duration flushPeriod, final QueueStorageType queueStorageBackend, final Duration retentionDuration,
+                                         final Clock timeSource, boolean enableScheduledFlusher) throws IOException {
+        this.timeSource = timeSource;
+
+        this.lockHandle = FileLockFactory.obtainLock(pathToQueue, SEGMENT_LOCK_PATH);
+        this.pathToQueue = pathToQueue;
+        this.segmentSizeLimit = segmentSizeLimit;
+        this.queueSizeLimit = queueSizeLimit;
+        this.queueStorageBackend = queueStorageBackend;
+        this.flushPeriod = flushPeriod;
+        this.queueSizeCounter = new AtomicLong(calculateQueueSize());
+        this.retentionDuration = retentionDuration;
+
+        cleanupTempLogFiles();
+        refreshOldestSegmentReference();
+        segmentIndex = listSegmentPaths(pathToQueue)
+                .map(segment -> segment.getFileName().toString().split("\\.")[0])
+                .mapToInt(Integer::parseInt)
+                .max().orElse(0);
+        createNextWriter();
+        this.lastEventTimestamp = Timestamp.now();
+        if (enableScheduledFlusher) {
+            initFlushScheduler();
+        }
+    }
+
+    public boolean isOpen() {
+        return isOpen.get();
+    }
+
+    public Path getPath() {
+        return pathToQueue;
+    }
+
+    public long getCurrentQueueSize() {
+        return queueSizeCounter.longValue();
+    }
+
+    public String getStoragePolicy() {
+        return queueStorageBackend.name().toLowerCase(Locale.ROOT);
+    }
+
+    public long getDroppedEvents() {
+        return droppedCount.longValue();
+    }
+
+    public long getExpiredEvents() {
+        return expiredCount.longValue();
+    }
+
+    public String getLastError() {
+        return lastErrorMessage;
+    }
+
+    public void writeDeadLetterEntry(Event inputEvent, String originPluginName, String originPluginId, String failureReason) throws IOException {
+        writeDeadLetterEntry(new DLQEntry(inputEvent, originPluginName, originPluginId, failureReason));
+    }
+
+    @Override
+    public void closeWriter() {
+        if (isOpen.compareAndSet(true, false)) {
+            try {
+                finalizeCurrentSegment(FinalizationPolicy.ALWAYS);
+            } catch (Exception exception) {
+                DLQ_LOG.warn("Unable to close dlq writer, ignoring", exception);
+            }
+            try {
+                releaseLock();
+            } catch (Exception exception) {
+                DLQ_LOG.warn("Unable to release fileLock, ignoring", exception);
+            }
+
+            try {
+                flushExecutor.shutdown();
+            } catch (Exception exception) {
+                DLQ_LOG.warn("Unable shutdown flush scheduler, ignoring", exception);
+            }
+        }
+    }
+
+    @VisibleForTesting
+    void writeDeadLetterEntry(DLQEntry dlqEntry) throws IOException {
+        guard.lock();
+        try {
+            Timestamp entryTime = Timestamp.now();
+            if (entryTime.compareTo(lastEventTimestamp) < 0) {
+                entryTime = lastEventTimestamp;
+            }
+            writeEntryInternal(dlqEntry);
+            lastEventTimestamp = entryTime;
+        } finally {
+            guard.unlock();
+        }
+    }
+
+    private void writeEntryInternal(DLQEntry dlqEntry) throws IOException {
+        Event inputEvent = dlqEntry.getEvent();
+
+        if (isAlreadyProcessed(inputEvent)) {
+            DLQ_LOG.warn("Event previously submitted to dead letter queue. Skipping...");
+            return;
+        }
+        byte[] recordBytes = dlqEntry.serialize();
+        int payloadSize = RECORD_HEADER_SIZE + recordBytes.length;
+        applyAgeRetentionPolicy();
+        boolean shouldSkipWrite = enforceStoragePolicy(payloadSize);
+        if (shouldSkipWrite) {
+            return;
+        }
+
+        if (wouldExceedSegmentSize(payloadSize)) {
+            finalizeCurrentSegment(FinalizationPolicy.ALWAYS);
+        }
+        long bytesWritten = activeWriter.writeEvent(recordBytes);
+        queueSizeCounter.getAndAdd(bytesWritten);
+        lastWriteTime = Instant.now();
+    }
+
+    private boolean wouldExceedSegmentSize(int payloadSize) throws IOException {
+        return activeWriter.getPosition() + payloadSize > segmentSizeLimit;
+    }
+
+    private void applyAgeRetentionPolicy() {
+        if (isOldestSegmentExpired()) {
+            try {
+                removeExpiredSegments();
+            } catch (IOException ioException) {
+                DLQ_LOG.error("Can't remove some DLQ files while cleaning expired segments", ioException);
+            }
+        }
+    }
+
+    /**
+     * @param payloadSize payload size in bytes.
+     * @return boolean true if event write has to be skipped.
+     * */
+    private boolean enforceStoragePolicy(int payloadSize) {
+        if (!wouldExceedMaxQueueSize(payloadSize)) {
+            return false;
+        }
+
+        // load currentQueueSize from filesystem because there could be a consumer
+        // that's already cleaning
+        try {
+            this.queueSizeCounter.set(calculateQueueSize());
+        } catch (IOException ioException) {
+            DLQ_LOG.warn("Unable to determine DLQ size, skipping storage policy check", ioException);
+            return false;
+        }
+
+        // after reload verify the condition is still valid
+        if (!wouldExceedMaxQueueSize(payloadSize)) {
+            return false;
+        }
+
+        if (queueStorageBackend == QueueStorageType.DROP_NEWER) {
+            lastErrorMessage = String.format("Cannot write event to DLQ(path: %s): reached maxQueueSize of %d", pathToQueue, queueSizeLimit);
+            DLQ_LOG.error(lastErrorMessage);
+            droppedCount.add(1L);
+            return true;
+        } else {
+            try {
+                do {
+                    removeOldestSegment();
+                } while (wouldExceedMaxQueueSize(payloadSize));
+            } catch (IOException ioException) {
+                DLQ_LOG.error("Can't remove some DLQ files while removing older segments", ioException);
+            }
+            return false;
+        }
+    }
+
+    private boolean wouldExceedMaxQueueSize(int payloadSize) {
+        return queueSizeCounter.longValue() + payloadSize > queueSizeLimit;
+    }
+
+    private boolean isOldestSegmentExpired() {
+        if (retentionDuration == null) {
+            return false;
+        }
+        final Instant currentInstant = timeSource.instant();
+        return oldestSegmentTime
+                .map(item -> item.toInstant().isBefore(currentInstant.minus(retentionDuration)))
+                .orElse(false);
+    }
+
+    private void removeExpiredSegments() throws IOException {
+        // remove all the old segments that verifies the age retention condition
+        boolean shouldCleanNext;
+        do {
+            if (oldestSegmentLocation.isPresent()) {
+                Path removedSegment = oldestSegmentLocation.get();
+                expiredCount.add(removeTailSegment(removedSegment, "age retention policy"));
+            }
+            refreshOldestSegmentReference();
+            shouldCleanNext = isOldestSegmentExpired();
+        } while (shouldCleanNext);
+
+        this.queueSizeCounter.set(calculateQueueSize());
+    }
+
+    /**
+     * Deletes the segment path, if present. Also return the number of events it contains.
+     *
+     * @param segmentPath
+     *      The segment file to delete.
+     * @param removalReason
+     *      Description of delete motivation.
+     * @return the number of events contained in the segment or 0 if the segment was already removed.
+     * @throws IOException if any other IO related error happens during deletion of the segment.
+     * */
+    private long removeTailSegment(Path segmentPath, String removalReason) throws IOException {
+        try {
+            long segmentEventCount = DeadLetterQueueUtils.countEventsInSegment(segmentPath);
+            Files.delete(segmentPath);
+            DLQ_LOG.debug("Removed segment file {} due to {}", removalReason, segmentPath);
+            return segmentEventCount;
+        } catch (NoSuchFileException noSuchFileException) {
+            // the last segment was deleted by another process, maybe the reader that's cleaning consumed segments
+            DLQ_LOG.debug("File not found {}, maybe removed by the reader pipeline", segmentPath);
+            return 0;
+        }
+    }
+
+    private void refreshOldestSegmentReference() throws IOException {
+        oldestSegmentLocation = listSegmentPaths(this.pathToQueue)
+                .filter(pathItem -> pathItem.toFile().length() > 1) // take the files that have content to process
+                .sorted()
+                .findFirst();
+        if (!oldestSegmentLocation.isPresent()) {
+            oldestSegmentTime = Optional.empty();
+            return;
+        }
+        // extract the newest timestamp from the oldest segment
+        Optional<Timestamp> maybeFoundTimestamp = readLastEventTimestampInSegment(oldestSegmentLocation.get());
+        if (!maybeFoundTimestamp.isPresent()) {
+            // clean also the last segment, because doesn't contain a timestamp (corrupted maybe)
+            // or is not present anymore
+            oldestSegmentLocation = Optional.empty();
+        }
+        oldestSegmentTime = maybeFoundTimestamp;
+    }
+
+    /**
+     * Extract the timestamp from the last DLQEntry it finds in the given segment.
+     * Start from the end of the latest block, and going backward try to read the next event from its start.
+     * */
+    private static Optional<Timestamp> readLastEventTimestampInSegment(Path pathToSegment) throws IOException {
+        final int finalBlockId = (int) Math.ceil(((Files.size(pathToSegment) - VERSION_SIZE) / (double) BLOCK_SIZE)) - 1;
+        byte[] eventData = null;
+        try (RecordIOReader readerInstance = new RecordIOReader(pathToSegment)) {
+            int currentBlockId = finalBlockId;
+            while (eventData == null && currentBlockId >= 0) { // no event present in last block, try with the one before
+                readerInstance.seekToBlock(currentBlockId);
+                eventData = readerInstance.readEvent();
+                currentBlockId--;
+            }
+        } catch (NoSuchFileException noSuchFileException) {
+            // the segment file may have been removed by the clean consumed feature on the reader side
+            return Optional.empty();
+        }
+        if (eventData == null) {
+            DLQ_LOG.warn("Cannot find a complete event into the segment file [{}], this is a DLQ segment corruption", pathToSegment);
+            return Optional.empty();
+        }
+        return Optional.of(DLQEntry.deserialize(eventData).getEntryTime());
+    }
+
+    // package-private for testing
+    void removeOldestSegment() throws IOException {
+        // remove oldest segment
+        final Optional<Path> earliestSegment = listSegmentPaths(pathToQueue)
+                .min(Comparator.comparingInt(DeadLetterQueueUtils::extractSegmentId));
+        if (earliestSegment.isPresent()) {
+            final Path removedSegment = earliestSegment.get();
+            removeTailSegment(removedSegment, "dead letter queue size exceeded dead_letter_queue.max_bytes size(" + queueSizeLimit + ")");
