+            DLQ_LOG.info("Queue size {} exceeded, but no complete DLQ segments found", queueSizeLimit);
+        }
+        this.queueSizeCounter.set(calculateQueueSize());
+    }
+
+    /**
+     * Method to determine whether the event has already been processed by the DLQ - currently this
