+     */
+    private static boolean isAlreadyProcessed(final Event inputEvent) {
+        return inputEvent.includes(DLQ_METADATA_KEY);
+    }
+
+    private void flushIfStale() {
+        try{
+            finalizeCurrentSegment(FinalizationPolicy.ONLY_IF_STALE);
+        } catch (Exception exception){
+            DLQ_LOG.warn("unable to finalize segment", exception);
+        }
+    }
+
+    /**
+     * Determines whether the current writer is stale. It is stale if writes have been performed, but the
+     * last time it was written is further in the past than the flush interval.
+     * @return
+     */
+    private boolean isCurrentWriterStale(){
+        return activeWriter.isStale(flushPeriod);
+    }
+
+    private void finalizeCurrentSegment(final FinalizationPolicy finalizationPolicy) throws IOException {
+        guard.lock();
+        try {
+            if (!isCurrentWriterStale() && finalizationPolicy == FinalizationPolicy.ONLY_IF_STALE)
+                return;
+
+            if (activeWriter != null) {
+                if (activeWriter.hasWritten()) {
+                    activeWriter.close();
+                    finalizeSegment(segmentIndex);
+                }
+                refreshOldestSegmentReference();
+                applyAgeRetentionPolicy();
+                if (isOpen() && activeWriter.hasWritten()) {
+                    createNextWriter();
+                }
+            }
+        } finally {
+            guard.unlock();
+        }
+    }
+
+    private void finalizeSegment(int targetSegmentIndex) throws IOException {
+        Files.move(pathToQueue.resolve(String.format(TEMP_FILENAME_PATTERN, targetSegmentIndex)),
+                pathToQueue.resolve(String.format(SEGMENT_FILENAME_PATTERN, targetSegmentIndex)),
+                StandardCopyOption.ATOMIC_MOVE);
+        DLQ_LOG.debug("Sealed segment with index {}", targetSegmentIndex);
+    }
+
+    private void initFlushScheduler() {
+        flushExecutor = Executors.newScheduledThreadPool(1, runner -> {
+            Thread item = new Thread(runner);
+            //Allow this thread to die when the JVM dies
+            item.setDaemon(true);
+            //Set the name
+            item.setName("dlq-flush-check");
+            return item;
+        });
+        flushExecutor.scheduleAtFixedRate(this::flushIfStale, 1L, 1L, TimeUnit.SECONDS);
+    }
+
+
+    private long calculateQueueSize() throws IOException {
+        return listSegmentPaths(this.pathToQueue)
+                .mapToLong(DeadLetterQueueSegmentWriter::getFileSizeSafely)
+                .sum();
+    }
+
+    private static long getFileSizeSafely(Path pathItem) {
+        try {
+            return Files.size(pathItem);
+        } catch (IOException exception) {
+            return 0L;
+        }
+    }
+
+    private void releaseLock() {
+        try {
+            FileLockFactory.releaseLock(lockHandle);
+        } catch (IOException exception) {
+            DLQ_LOG.debug("Unable to release fileLock", exception);
+        }
+        try {
+            Files.deleteIfExists(pathToQueue.resolve(SEGMENT_LOCK_PATH));
+        } catch (IOException exception){
+            DLQ_LOG.debug("Unable to delete fileLock file", exception);
+        }
+    }
+
+    private void createNextWriter() throws IOException {
+        activeWriter = new RecordIOWriter(pathToQueue.resolve(String.format(TEMP_FILENAME_PATTERN, ++segmentIndex)));
+        queueSizeCounter.incrementAndGet();
+    }
+
+    // Clean up existing temp files - files with an extension of .log.tmp. Either delete them if an existing
+    // segment file with the same base name exists, or rename the
+    // temp file to the segment file, which can happen when a process ends abnormally
+    private void cleanupTempLogFiles() throws IOException {
+        listFiles(pathToQueue, ".log.tmp")
+                .forEach(this::finalizeTempFile);
+    }
+
+    // check if there is a corresponding .log file - if yes delete the temp file, if no atomic move the
+    // temp file to be a new segment file..
+    private void finalizeTempFile(final Path temporaryFile) {
+        String computedSegmentName = temporaryFile.getFileName().toString().split("\\.")[0];
+        Path segmentFilePath = pathToQueue.resolve(String.format("%s.log", computedSegmentName));
+        try {
+            if (Files.exists(segmentFilePath)) {
+                Files.delete(temporaryFile);
+            }
+            else {
+                SegmentStatus statusOfSegment = RecordIOReader.getSegmentStatus(temporaryFile);
+                switch (statusOfSegment){
+                    case VALID:
+                        DLQ_LOG.debug("Moving temp file {} to segment file {}", temporaryFile, segmentFilePath);
+                        Files.move(temporaryFile, segmentFilePath, StandardCopyOption.ATOMIC_MOVE);
+                        break;
+                    case EMPTY:
+                        deleteTempFile(temporaryFile, computedSegmentName);
+                        break;
+                    case INVALID:
+                        Path errorRecordFile = pathToQueue.resolve(String.format("%s.err", computedSegmentName));
+                        DLQ_LOG.warn("Segment file {} is in an error state, saving as {}", segmentFilePath, errorRecordFile);
+                        Files.move(temporaryFile, errorRecordFile, StandardCopyOption.ATOMIC_MOVE);
+                        break;
+                    default:
+                        throw new IllegalStateException("Unexpected value: " + RecordIOReader.getSegmentStatus(temporaryFile));
+                }
+            }
+        } catch (IOException exception) {
+            throw new IllegalStateException("Unable to clean up temp file: " + temporaryFile, exception);
+        }
+    }
+
+    // Windows can leave files in a "Delete pending" state, where the file presents as existing to certain
+    // methods, and not to others, and actively prevents a new file being created with the same file name,
+    // throwing AccessDeniedException. This method moves the temporary file to a .del file before
+    // deletion, enabling a new temp file to be created in its place.
+    private void deleteTempFile(Path temporaryFile, String computedSegmentName) throws IOException {
+        Path targetToDelete;
+        if (isWindows()) {
+            Path removedFile = pathToQueue.resolve(String.format("%s.del", computedSegmentName));
+            DLQ_LOG.debug("Moving temp file {} to {}", temporaryFile, removedFile);
+            targetToDelete = removedFile;
+            Files.move(temporaryFile, removedFile, StandardCopyOption.ATOMIC_MOVE);
+        } else {
+            targetToDelete = temporaryFile;
+        }
+        Files.delete(targetToDelete);
+    }
+
+    private static boolean isWindows() {
+        return System.getProperty("os.name").startsWith("Windows");
+    }
+}
