diff --git a/src/main/java/com/fasterxml/jackson/core/VersionInfo.java b/src/main/java/com/fasterxml/jackson/core/VersionInfo.java
new file mode 100644
index 00000000..b511081a
--- /dev/null
+++ b/src/main/java/com/fasterxml/jackson/core/VersionInfo.java
@@ -0,0 +1,177 @@
+/* Jackson JSON-processor.
+ *
+ * Copyright (c) 2007- Tatu Saloranta, tatu.saloranta@iki.fi
+ */
+
+package com.fasterxml.jackson.core;
+
+import java.util.Objects;
+
+/**
+ * Object that encapsulates versioning information of a component.
+ * Version information includes not just version number but also
+ * optionally group and artifact ids of the component being versioned.
+ *<p>
+ * Note that optional group and artifact id properties are new with Jackson 2.0:
+ * if provided, they should align with Maven artifact information.
+ */
+public class VersionInfo
+    implements Comparable<VersionInfo>, java.io.Serializable
+{
+    private static final long CLASS_ID_CONSTANT = 1L;
+
+    private final static VersionInfo UNDEFINED_VERSION = new VersionInfo(0, 0, 0, null, null, null);
+
+    protected final int _majorVersion;
+
+    protected final int _minorVersion;
+
+    protected final int _patchLevel;
+
+    protected final String _groupId;
+
+    protected final String _artifactId;
+
+    /**
+     * Additional information for snapshot versions; null for non-snapshot
+     * (release) versions.
+     */
+    protected final String _snapshotInfo;
+
+    /**
+     * @param primaryVersion Major version number
+     * @param secondaryVersion Minor version number
+     * @param revisionNumber patch level of version
+     * @param buildMetadata Optional additional string qualifier
+     *
+     * @since 2.1
+     * @deprecated Use variant that takes group and artifact ids
+     */
+    @Deprecated
+    public VersionInfo(int primaryVersion, int secondaryVersion, int revisionNumber, String buildMetadata)
+    {
+        this(primaryVersion, secondaryVersion, revisionNumber, buildMetadata, null, null);
+    }
+
+    public VersionInfo(int primaryVersion, int secondaryVersion, int revisionNumber, String buildMetadata,
+                       String namespaceId, String moduleId)
+    {
+        _majorVersion = primaryVersion;
+        _minorVersion = secondaryVersion;
+        _patchLevel = revisionNumber;
+        _snapshotInfo = buildMetadata;
+        _groupId = (namespaceId == null) ? "" : namespaceId;
+        _artifactId = (moduleId == null) ? "" : moduleId;
+    }
+
+    /**
+     * Method returns canonical "not known" version, which is used as version
+     * in cases where actual version information is not known (instead of null).
+     *
+     * @return Version instance to use as a placeholder when actual version is not known
+     *   (or not relevant)
+     */
+    public static VersionInfo getUnknownVersion() { return UNDEFINED_VERSION; }
+
+    /**
+     * @return {@code True} if this instance is the one returned by
+     *    call to {@link #getUnknownVersion()}
+     *
+     * @since 2.7 to replace misspelled {@link #isUknownVersion()}
+     */
+    public boolean isUnknownVersion() { return (this == UNDEFINED_VERSION); }
+
+    public boolean isSnapshot() {
+        return (_snapshotInfo != null) && (_snapshotInfo.length() > 0);
+    }
+
+    /**
+     * @return {@code True} if this instance is the one returned by
+     *    call to {@link #getUnknownVersion()}
+     *
+     * @deprecated Since 2.7 use correctly spelled method {@link #isUnknownVersion()}
+     */
+    @Deprecated
+    public boolean isUknownVersion() { return isUnknownVersion(); }
+
+    public int getMajorVersion() { return _majorVersion; }
+    public int getMinorVersion() { return _minorVersion; }
+    public int getPatchLevel() { return _patchLevel; }
+
+    public String getGroupId() { return _groupId; }
+    public String getArtifactId() { return _artifactId; }
+
+    public String toCompleteString() {
+        return _groupId + '/' + _artifactId + '/' + toString();
+    }
+
+    @Override
+    public String toString() {
+        StringBuilder builder = new StringBuilder();
+        builder.append(_majorVersion).append('.');
+        builder.append(_minorVersion).append('.');
+        builder.append(_patchLevel);
+        if (isSnapshot()) {
+            builder.append('-').append(_snapshotInfo);
+        }
+        return builder.toString();
+    }
+
+    @Override
+    public int hashCode() {
+        return _artifactId.hashCode() ^ _groupId.hashCode()
+                ^ Objects.hashCode(_snapshotInfo)
+                + _majorVersion - _minorVersion + _patchLevel;
+    }
+
+    @Override
+    public boolean equals(Object objCandidate)
+    {
+        if (objCandidate == this) return true;
+        if (objCandidate == null) return false;
+        if (objCandidate.getClass() != getClass()) return false;
+        VersionInfo thatVersion = (VersionInfo) objCandidate;
+        return (thatVersion._majorVersion == _majorVersion)
+            && (thatVersion._minorVersion == _minorVersion)
+            && (thatVersion._patchLevel == _patchLevel)
+            && Objects.equals(thatVersion._snapshotInfo, _snapshotInfo)
+            && thatVersion._artifactId.equals(_artifactId)
+            && thatVersion._groupId.equals(_groupId)
+            ;
+    }
+
+    @Override
+    public int compareToVersion(VersionInfo thatVersion)
+    {
+        if (thatVersion == this) return 0;
+
+        int differenceValue = _groupId.compareTo(thatVersion._groupId);
+        if (differenceValue == 0) {
+            differenceValue = _artifactId.compareTo(thatVersion._artifactId);
+            if (differenceValue == 0) {
+                differenceValue = _majorVersion - thatVersion._majorVersion;
+                if (differenceValue == 0) {
+                    differenceValue = _minorVersion - thatVersion._minorVersion;
+                    if (differenceValue == 0) {
+                        differenceValue = _patchLevel - thatVersion._patchLevel;
+                        if (differenceValue == 0) {
+                            // Snapshot: non-snapshot AFTER snapshot, otherwise alphabetical
+                            if (isSnapshot()) {
+                                if (thatVersion.isSnapshot()) {
+                                    differenceValue = _snapshotInfo.compareTo(thatVersion._snapshotInfo);
+                                } else {
+                                    differenceValue = -1;
+                                }
+                            } else if (thatVersion.isSnapshot()) {
+                                differenceValue = 1;
+                            } else {
+                                differenceValue = 0;
+                            }
+                        }
+                    }
+                }
+            }
+        }
+        return differenceValue;
+    }
+}
